(() => {
'use strict';
const D=window.QUIZ_DATA,M=window.CivicMatching,P=(window.CIVIC_PROFILES?.profiles??[]).filter(p=>!p.retired),app=document.querySelector('#app'),KEY='civic-spectrum-history-v3',S=window.CivicSession,LEGACY=window.CIVIC_LEGACY_QUESTIONS;
const R=window.CivicTemporaryRanking??M,temporaryRanking=R.ENABLED===true;
const fields=['Politics','Philosophy','Political theory','Legal theory','Economics','Theology','Social','Foreign policy'];
const scale=['Strongly disagree','Disagree','Neutral','Agree','Strongly agree'];
let answers=Array(D.questions.length).fill(null),index=0,view='home',peopleTab='overall',countryTab='Modern',resultTab='overview',storageAvailable=true,shared=false,state=S.empty(),editing=false,queue=null,activeSnapshot=null;
const evidenceVersion=S.fingerprint([M.VERSION,temporaryRanking?R.VERSION:null,P,window.CIVIC_AFFILIATIONS??null]),questionVersion=S.questionVersion(D.questions);
let legacyImported=false;
let revealIndex=null,revealItems=[],revealPaused=false,revealTimer=null;
const reducedMotion=()=>window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches===true;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function valid(a,qs=D.questions){return Array.isArray(a)&&a.length===qs.length&&a.every((v,i)=>S.validAnswer(qs[i],v));}
try{const raw=localStorage.getItem(KEY),v2=localStorage.getItem('civic-spectrum-v2'),v1=localStorage.getItem('civic-spectrum-v1');state=S.load(raw,v2??v1,D.questions,LEGACY,!v2);legacyImported=raw===null&&!!(v2??v1);answers=S.align(state.draft.entries,D.questions);index=Math.max(0,D.questions.findIndex(q=>q.id===state.draft.indexId));editing=state.draft.flow==='review';}catch{storageAvailable=false;}
function decodeHash(){const match=location.hash.match(/^#r=([A-Za-z0-9_-]+)$/);if(!match)return false;try{let candidate;const payload=JSON.parse(atob(match[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload?.version===3){if(!payload.entries||typeof payload.entries!=='object'||Array.isArray(payload.entries))throw Error();candidate=S.align(payload.entries,D.questions);}else{const legacy=Array.isArray(payload),a=legacy?payload:payload?.version===2?payload.answers:null;if(!valid(a,LEGACY)||a.some(x=>x===null))throw Error();const records=S.entries(LEGACY,a);if(legacy&&a[48]===2)records.Q49.value=null;candidate=S.align(records,D.questions);}if(!candidate.some(a=>a!==null))throw Error();answers=candidate;shared=true;view='results';return true;}catch{toast('This result link is invalid or its questions have changed. Your saved answers are unchanged.');return false;}}
function persist(){if(shared||!storageAvailable)return false;S.update(state,D.questions,answers,index);state.draft.flow=editing?'review':queue?'supplement':'quiz';try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageAvailable=false;toast('History could not be saved. Download a backup before leaving this page.');return false;}}
function answered(){return answers.filter(x=>x!==null).length;}
function substantive(q){return Number.isInteger(answers[D.questions.indexOf(q)]);}
function val(q){const a=answers[D.questions.indexOf(q)];if(!Number.isInteger(a))return null;if(q.type==='scale')return [-1,-.5,0,.5,1][a]*q.sign;return q.values?q.values[a]:null;}
// Complementary companion colors, one curated pairing per dimension.
const axisCompanions=['#72b9aa','#dca87b','#85bca4','#88aacb','#9997c6','#9aadd0','#ddab91','#c399bb','#c299b6','#b39aca','#cdaa7e','#d3a286','#a3bd83'];
function stats(){return D.axes.map((a,i)=>{const qs=D.questions.filter(q=>q.axis===i),values=qs.map(val).filter(v=>v!==null);return {...a,rightColor:axisCompanions[i],n:qs.filter(substantive).length,scored:values.length,v:values.length?values.reduce((s,v)=>s+v,0)/values.length:null};});}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3800);}
function change(v){if(v!=='results'){clearTimeout(revealTimer);revealIndex=null;}view=v;render();window.scrollTo({top:0,behavior:'instant'});}
function home(){const n=answered();return `<section class="hero"><div><span class="eyebrow">A FIELD GUIDE TO YOUR CONVICTIONS</span><h1>A clearer picture<br>of what you <span>believe.</span></h1><p class="hero-description">${D.questions.length} thoughtful questions. Discover the principles behind your convictions, and the people whose documented views are closest to yours.</p><div class="hero-actions"><button class="primary" data-action="start">${n?'Start a new test':'Discover your outlook'} <span aria-hidden="true">→</span></button>${n?`<button class="secondary" data-action="resume">${editing?'Continue review':n===D.questions.length?'View your results':'Resume · '+n+'/'+D.questions.length}</button>`:''}</div>${savedControls()}<p class="small muted"><span class="status-dot"></span>No account required · ${storageAvailable?'Saved in this browser; download a backup for safekeeping.':'Storage unavailable. Download a backup before leaving.'}</p><div class="stats"><div class="stat"><strong>${D.questions.length}</strong><span>Questions</span></div><div class="stat"><strong>13</strong><span>Dimensions</span></div><div class="stat"><strong>8</strong><span>Match fields</span></div></div><p class="landing-warning">Expanded edition: 78 original questions plus ${D.questions.length-78} optional supplements on rights, public policy, AI, and economic institutions. Explore your answers and source-backed comparisons. Evidence coverage is shown for every match.</p></div><div class="portrait"><div class="portrait-heading"><span>THE SHAPE OF AN OUTLOOK</span><span aria-hidden="true">↗</span></div>${[0,3,6,7,9,12].map((k,i)=>{const a=D.axes[k],p=[64,43,73,35,58,79][i];return `<div class="sample-row"><div><span>${a.short}</span><span style="color:${a.color}">${i===0?'Recognition':i===1?'Prudence':i===2?'Mixed rule':i===3?'Autonomy':i===4?'Coordination':'Precaution'}</span></div><div class="mini-track"><i style="width:${p}%;background:${a.color}"></i></div></div>`;}).join('')}<p class="portrait-label">Illustrative graphic · Your answers tell your own story</p></div></section><section class="feature-row"><div class="feature"><span class="feature-num">01</span><div><h3>Questions with room for nuance</h3><p>Choose between distinct positions, including qualified answers where a simple yes or no is not enough.</p></div></div><div class="feature"><span class="feature-num">02</span><div><h3>Principles, institutions, and policy</h3><p>Separate the ends of politics from who governs, how power is shared, and what the law should enforce.</p></div></div><div class="feature"><span class="feature-num">03</span><div><h3>A portrait you can revisit</h3><p>Review every answer, explore your dimensions, and export your result card.</p></div></div></section>`;}
function context(q){if(!window.CIVIC_LEGACY_QUESTIONS.some(old=>old.id===q.id))return '';if(q.axis<2)return 'Imagine a historically Christian country whose citizens hold differing religious beliefs. “The Church” means the ecclesiastical authority recognized by the proposed establishment.';if(q.axis===2&&q.id!=='Q14')return 'Answer according to what you consider morally or socially desirable, whether or not the law should enforce it.';if(q.axis===4)return 'Assume a country with a written constitution and courts empowered to interpret it.';if(q.axis===12)return '“Frontier AI” means the most capable general-purpose AI systems, rather than every use of machine learning.';return '';}
function quiz(){
 const q=D.questions[index],opts=q.type==='scale'?scale:q.options,n=answered(),supplementIndex=queue?.indexOf(index)??-1,canGoBack=queue?supplementIndex>0:index>0;
 const chapter=D.axes[q.axis],progress=editing?index+1:n;
 return `<div class="quiz-shell" style="--chapter-color:${chapter.color}"><aside class="quiz-sidebar"><span class="eyebrow">YOUR POLITICAL PORTRAIT</span><span class="chapter-number">${String(q.axis+1).padStart(2,'0')}<small> / 13</small></span><h2>${esc(chapter.name)}</h2><p class="chapter-caption">Take a position. Leave room for nuance.</p><div class="chapter-list">${D.axes.map((a,i)=>`<span class="${i===q.axis?'current':''}" ${i===q.axis?'aria-current="step"':''}><i></i>${esc(a.short)}</span>`).join('')}</div><button class="text-button" data-action="review">Question overview ↗</button></aside><div class="quiz-main"><div class="quiz-topbar"><div class="quiz-nav"><button class="text-button" data-action="back" ${!canGoBack?'disabled':''}>← Back</button><button class="${editing?'secondary':'primary'}" data-action="next" ${answers[index]===null?'disabled':''}>${index===D.questions.length-1?'Submit results':'Next question'} <span aria-hidden="true">→</span></button>${editing?`<button class="primary review-submit" data-action="results" ${answered()===0?'disabled':''}>Submit updated results</button>`:''}</div><div class="quiz-meta"><span>${editing?'REVISITING YOUR ANSWERS':queue?'CONTINUING YOUR PORTRAIT':esc(chapter.short).toUpperCase()}</span><span>${queue?`Supplement ${supplementIndex+1} of ${queue.length} · `:''}Question ${index+1} of ${D.questions.length}</span></div></div><div class="progress" role="progressbar" aria-label="${editing?'Review position':'Questions answered'}" aria-valuemin="0" aria-valuemax="${D.questions.length}" aria-valuenow="${progress}"><i style="width:${progress/D.questions.length*100}%"></i></div><section class="question-card" aria-labelledby="question-title"><span class="question-id">${q.id} / YOUR POSITION</span><h1 id="question-title" tabindex="-1">${esc(q.text)}</h1>${context(q)?`<p class="context">${esc(context(q))}</p>`:''}${q.note?`<p class="context">${esc(q.note)}</p>`:''}<div class="answer-list ${q.type==='scale'?'is-scale':'is-choice'}">${opts.map((o,i)=>`<button class="answer ${q.type==='scale'?'scale':''}" data-answer="${i}" data-index="${i}" aria-pressed="${answers[index]===i}"><span class="radio" aria-hidden="true">${i+1}</span><span>${esc(o)}</span><span class="answer-tick" aria-hidden="true">✓</span></button>`).join('')}</div><div class="other-options">${q.type==='choice'?`<button class="answer" data-answer="m" aria-pressed="${answers[index]==='m'}">Other / mixed view</button>`:''}<button class="answer" data-answer="u" aria-pressed="${answers[index]==='u'}">Unsure</button></div></section><div class="quiz-actions"><p class="save-note">${shared?'Shared answers · Your personal history stays separate.':storageAvailable?'Saved on this device.':'Browser storage is unavailable; keep this page open.'} <button class="text-button" data-action="save-exit">Save & exit</button></p><p class="keyboard-hint">Click an answer to move on automatically.${editing?' Saved choices are selected. Use Submit updated results whenever you are ready.':''} <span>Keys 1–${opts.length} to answer.</span></p></div></div></div>`;
}

const choiceLabels={Q28:['Original public meaning','Precedent & tradition','Objective moral principles','Evolving social values'],Q30:['Text & original meaning','Precedent & reliance','Natural justice & common good','Contemporary suitability'],Q31:['Continuing consent','Constitutional participation','Historical allegiance','Justice & common good'],Q32:['Independent individual rights','Human nature & dignity','Common-good foundation','Institution-created rights'],Q34:['Individual arrangement','Combined individual welfare','Irreducible common good','Collective primacy'],Q43:['City-states & autonomous zones','Loose confederation','Federation','Unitary with local powers','Highly centralized state'],Q49:['Private enterprise','Distributed private ownership','Private ownership / central directives','Public major industries','Public / communal ownership'],Q61:['Civic membership','Shared culture','Religious-cultural tradition','Ancestral membership'],Q67:['Nonviolent resistance','National defense','Collective defense','Atrocity prevention','Strategic interests','Power / territorial expansion'],Q72:['Absolute civilian protection','Extreme-emergency exception','Consequential exception','Strategic calculation'],Q73:['Unrestricted acceleration','Limited safeguards','Regulated development','Conditional pause','Indefinite moratorium']};
function labelFor(id){const q=D.questions.find(x=>x.id===id),a=answers[D.questions.findIndex(q=>q.id===id)];if(!Number.isInteger(a))return null;return choiceLabels[id]?.[a]??q.options?.[a]??scale[a];}
const categoryQuestions={4:'Q28',5:'Q31',8:'Q49',9:'Q55',10:'Q61',11:'Q67'};
function categoryState(i){const q=D.questions.find(q=>q.id===categoryQuestions[i]),answer=answers[D.questions.indexOf(q)];return {q,answer,selected:Number.isInteger(answer),label:labelFor(q.id)??(answer==='u'?'Unsure':answer==='m'?'Other / mixed view':'No substantive position recorded')};}
function categoryBar(a,i){const state=categoryState(i);return `<div class="axis-labels"><span>Position options · ${state.q.id}</span><span>${state.selected?'Option '+(state.answer+1)+' of '+state.q.options.length:'No option selected'}</span></div><div class="axis-track category-track" role="img" aria-label="${esc(a.name+': '+state.label)}">${state.q.options.map((option,j)=>`<span class="category-segment ${state.selected&&j===state.answer?'selected':''}" style="--axis-color:${a.color}" title="${esc(option)}" aria-hidden="true"></span>`).join('')}</div><div class="axis-value">${esc(state.label)} <span class="small">· categorical position</span></div>`;}
function axisCards(){return stats().map((a,i)=>{const rows=D.questions.filter(q=>q.axis===i),p=a.v===null?0:Math.round((a.v+1)*50),cs=i===0?doctrine('Church–state arrangements'):null;return `<article class="axis-card"><div class="axis-title"><span>${a.name}</span><small>${a.n}/${rows.length} substantive</small></div>${categoryQuestions[i]?categoryBar(a,i):`<div class="axis-labels"><span>${a.left}</span><span>${a.right}</span></div><div class="axis-track ${a.v===null?'empty-bar':''}" role="img" aria-label="${esc(a.name+': '+(a.v===null?'Insufficient answers':a.v<0?a.left:a.right))}">${a.v===null?'':`<div class="axis-left" style="width:${p}%;background:${a.color}"></div><div class="axis-right" style="width:${100-p}%;background:${a.rightColor}"></div><i class="axis-marker" style="left:${p}%" aria-hidden="true"></i>`}</div><div class="axis-value">${a.v===null?'Insufficient answers':Math.abs(a.v)<.15?'Mixed directional answers':a.v<0?a.left:a.right} <span class="small">· provisional summary</span></div>${cs?`<div class="axis-value">Closest arrangement: <b>${esc(cs.profile.name)}</b></div>`:''}`}<details><summary>View these answers</summary><ul class="position-list">${rows.map(q=>{const ans=answers[D.questions.indexOf(q)],text=ans==='u'?'Unsure':ans==='m'?'Other / mixed view':ans===null?'Unanswered':q.type==='scale'?scale[ans]:q.options[ans];return `<li><b>${q.id}</b> ${esc(q.text)}<br><span style="color:${a.color}">${esc(text)}</span></li>`;}).join('')}</ul></details></article>`;}).join('');}
function profileFor(id){return P.find(p=>p.id===id);}
function resultName(p){if(p.kind==='Country')return D.countries.find(c=>c.name===p.name)?.short??p.name;return p.name;}
function positionAnswer(q,a){return q.type==='scale'?scale[a]:q.options[a];}
function sourceLinks(p,ids){return ids.map(id=>p.sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`).join(' · ');}
function evidenceLabel(pos){return pos.basis==='explicit'?'Directly documented':(pos.rationale??'').startsWith('Provisional L50 v2: ')?'Broader inference':'Source-backed interpretation';}
function evidenceCounts(items){const counts={};for(const x of items){const label=evidenceLabel(x.position);counts[label]=(counts[label]??0)+1;}return Object.entries(counts).map(([label,n])=>n+' '+label.toLowerCase()).join(' · ');}
function witness(p,r,title){return `<div class="match-evidence"><b>${title} · ${r.id}</b><p>${esc(r.question.text)}</p><p><span class="muted">Your answer:</span> ${esc(positionAnswer(r.question,r.answer))}</p><p><span class="muted">Profile:</span> ${r.options.map(a=>esc(positionAnswer(r.question,a))).join(' / ')}</p><p>${esc(r.position.rationale)}</p><span class="basis">${evidenceLabel(r.position)}</span><div class="evidence-links">${sourceLinks(p,r.position.sourceIds)}</div></div>`;}
function comparisonCoverage(p){
 const sample=Array(D.questions.length).fill(0),catalog=D.catalog.find(c=>c.id===p.id);
 const scope=p.kind==='AI personality'?'AI outlook':p.kind==='Supplementary profile'?catalog?.fields?.[0]:'overall';
 const result=M.scoreProfile(p,sample,D.questions,scope),fields=Object.keys(M.FIELDS).filter(f=>(p.kind!=='Political personality'||catalog?.fields?.includes(f))&&M.scoreProfile(p,sample,D.questions,f)?.availableEligible);
 const title=scope==='overall'?'Overall':scope;
 return `<div class="comparison-coverage"><p><b>${esc(title)} comparison:</b> ${result?.availableEligible?'Available':'Not enough documented coverage'} · ${result?.available??0}/${result?.total??0} questions${scope==='overall'?' · '+result.availableAxes+'/12 dimensions':''}</p>${fields.length?`<p><b>Available fields:</b> ${fields.map(esc).join(' · ')}</p>`:'<p>No field yet meets its evidence requirement.</p>'}<p class="small muted">Availability describes the researched evidence. Your matches also depend on which questions you answer. Undocumented positions stay unknown.</p></div>`;
}
function researchGaps(p){const gaps=Object.entries(p.researchGaps??{}).filter(([id])=>!p.positions?.[id]);return gaps.length?`<details><summary>Why ${gaps.length} reviewed supplemental questions are not compared</summary><p>These are limits of this profile’s evidence or applicability, not missing answers from you.</p>${gaps.map(([id,reason])=>`<div class="match-evidence"><b>${esc(id)}</b><p>${esc(D.questions.find(q=>q.id===id)?.text??id)}</p><p>${esc(reason)}</p></div>`).join('')}</details>`:'';}
function researchDetails(p){const positions=Object.entries(p.positions??{});return `<details class="research-details"><summary>Evidence & profile limits</summary>${comparisonCoverage(p)}${researchGaps(p)}<p class="small muted">${esc(evidenceCounts(positions.map(([,position])=>({position}))))}. Source-backed interpretations apply cited material to a quiz answer; broader inferences are provisional L50 extrapolations. These labels describe how mappings were developed, not a separate accuracy rating.</p><p>${esc(p.notes??'')}</p>${p.period?`<p><b>Period:</b> ${esc(p.period)}</p>`:''}<ul>${p.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a> <span class="muted">(${esc(s.type)})</span></li>`).join('')}</ul><details><summary>All ${positions.length} question mappings</summary>${positions.map(([id,pos])=>{const q=D.questions.find(q=>q.id===id);return q?`<div class="match-evidence"><b>${id}</b><p>${esc(q.text)}</p><p>${pos.answers.map(a=>esc(positionAnswer(q,a))).join(' / ')}</p><p>${esc(pos.rationale)}</p><span class="basis">${evidenceLabel(pos)}</span><div class="evidence-links">${sourceLinks(p,pos.sourceIds)}</div></div>`:'';}).join('')}</details></details>`;}
function portrait(p,large=false){
 const photo=window.CIVIC_PORTRAITS?.[p.id],initials=p.name.split(/\s+/).map(n=>n[0]).slice(0,2).join('');
 return `<div class="person-portrait ${large?'reveal-photo':''} ${photo?'':'portrait-fallback'}"><span class="portrait-monogram" aria-hidden="true">${esc(initials)}</span>${photo?`<img src="${esc(photo.src)}" alt="Portrait of ${esc(p.name)}" width="640" height="800" loading="${large?'eager':'lazy'}" decoding="async">`:'<span class="portrait-unavailable">Portrait unavailable</span>'}</div>`;
}
function portraitCredit(p){const photo=window.CIVIC_PORTRAITS?.[p.id];return photo?`<details class="portrait-credit"><summary>Portrait credit</summary><p>${esc(photo.credit)} · <a href="${esc(photo.licenseUrl??photo.sourceUrl)}" target="_blank" rel="noopener">${esc(photo.license)}</a> · <a href="${esc(photo.sourceUrl)}" target="_blank" rel="noopener">Original image</a>. Displayed with a crop.</p></details>`:'';}
function religionMarkup(r){if(!r.religion)return '';const a=r.religion;return `<div class="notice small"><b>Religious affiliation · 30% of this match</b><p>You: ${esc(positionAnswer(a.question,a.answer))} · Profile: ${a.options.map(x=>esc(positionAnswer(a.question,x))).join(' / ')}. A shared documented affiliation adds up to 30 points; a conflicting one subtracts up to 30 points. Policy similarity: ${r.policyRaw.toFixed(1)}%; policy contributes 70%.</p><p>${esc(a.position.rationale)}</p>${sourceLinks({sources:a.sources},a.position.sourceIds)}</div>`;}
function matchReasons(r,limit=2){return `${religionMarkup(r)}<div class="match-reasons"><span class="eyebrow">WHY THIS MATCH</span>${r.agreements.length?r.agreements.slice(0,limit).map(x=>`<div class="reason-item"><p>${esc(x.question.text)}</p><p class="reason-answer"><span>You: <b>${esc(positionAnswer(x.question,x.answer))}</b></span><span>Profile: <b>${x.options.map(a=>esc(positionAnswer(x.question,a))).join(' / ')}</b></span></p></div>`).join(''):'<p>This is a relative match across the documented answers. No individual answer shows strong agreement.</p>'}${r.differences.length?`<div class="reason-item"><b>${r.differences[0].options.includes(r.differences[0].answer)?'Qualified agreement':'Important difference'}</b><p>${esc(r.differences[0].question.text)}</p><p class="reason-answer"><span>You: ${esc(positionAnswer(r.differences[0].question,r.differences[0].answer))}</span><span>Profile: ${r.differences[0].options.map(a=>esc(positionAnswer(r.differences[0].question,a))).join(' / ')}</span></p></div>`:''}<p class="small muted">Similarity across ${r.compared} comparable answers${r.scope==='overall'?` and ${r.axes} dimensions`:''}; not agreement with everything this person or tradition represents.</p></div>`;}
// Hold research and scoring fixed: this isolates the latest supplement's effect.
function calculationDetails(r){
 const supplementIds=D.questions.filter(q=>/^Q9[1-9]$/.test(q.id)).map(q=>q.id);
 const relevant=supplementIds.filter(id=>M.scopeIds(D.questions,r.scope).includes(id));
 const baseline=answers.map((a,i)=>supplementIds.includes(D.questions[i].id)?null:a);
 const before=M.scoreProfile(r.profile,baseline,D.questions,r.scope);
 const used=r.comparedIds.filter(id=>relevant.includes(id));
 const undocumented=relevant.filter(id=>!M.isSupported(r.profile,r.profile.positions?.[id]));
 const unanswered=relevant.filter(id=>!undocumented.includes(id)&&!used.includes(id));
 const effect=before.raw!==null&&r.raw!==null?r.raw-before.raw:null;
 const dimensions=[...new Set(r.items.map(x=>x.axis))].map(axis=>{const items=r.items.filter(x=>x.axis===axis),weight=items.reduce((sum,x)=>sum+x.weight,0);return {axis,fit:100*items.reduce((sum,x)=>sum+x.similarity*x.weight,0)/weight,count:items.length};}).sort((a,b)=>a.fit-b.fit);
 const axisBreakdown=r.scope==='overall'?`<p><b>What holds the overall percentage down?</b> Each of the ${dimensions.length} policy dimensions contributes equally within the ${r.religion?"70% policy component":"policy score"}. Economic answers affect their own dimensions; they do not replace disagreements elsewhere.</p><ul>${dimensions.map(x=>`<li>${esc(D.axes[x.axis].name)}: ${x.fit.toFixed(1)}% similarity · ${x.count} compared answers · ${(100*(r.religion?.weight?1-r.religion.weight:1)/dimensions.length).toFixed(1)}% of final score weight${x.count===1?' · Single-question dimension: especially sensitive to this answer.':''}</li>`).join('')}</ul>`:'';

 return `<details class="calculation-details"><summary>How this score is calculated · ${esc(r.scope==='overall'?'Overall':r.scope)}</summary>${r.equalization?`<p><b>Temporary ranking: ${r.equalization.rankingScore}%.</b> Every candidate uses the same ${r.equalization.answeredQuestions} substantive questions in this scope. Unknown evidence contributes 50; supported evidence contributes 50 + evidence weight × (item similarity − 50). Overall dimensions are averaged equally; other fields average questions. The existing religion adjustment applies afterward where relevant. The documented similarity below remains ${r.score}% and uses only supported comparisons.</p>`:''}<p>${r.scope==='Economics'?'Evidence-weighted average of compared answers.':'Evidence-weighted average within each represented dimension, then equal weighting of those dimensions.'} Directly documented answers, source-backed interpretations and broader inferences all retain normal scoring weight. Evidence labels do not reduce scoring weight. Uncertain inferred alternatives use their average similarity. The broad capital-mobilization question Q91 counts at half the usual weight for both explicit and inferred mappings.${r.scope==='Economics'?' Q100 counts twice for every profile with a supported mapping; this emphasis does not apply to overall results. A clear disagreement across the protective-tariff divide also subtracts up to 20 percentage points for both explicit and inferred mappings, only when every researched alternative is on the opposing side.':''}</p>${relevant.length?`<p><b>Latest supplement (Q91–Q99):</b> ${used.length} of ${relevant.length} used${used.length?' ('+used.join(', ')+')':''}.</p>${undocumented.length?`<p>No supported mapping; no score effect: ${undocumented.join(', ')}.</p>`:''}${unanswered.length?`<p>Mapped but not answered substantively: ${unanswered.join(', ')}.</p>`:''}${effect!==null?`<p>With current research and scoring held fixed: ${before.raw.toFixed(2)}% before these supplement answers → ${r.raw.toFixed(2)}% with them (${effect>=0?'+':''}${effect.toFixed(2)} percentage points).${!before.eligible?' The baseline does not meet ranking eligibility; it is a diagnostic only.':''}</p>`:'<p>No comparable baseline answers for isolating the supplement effect.</p>'}<p class="small muted">This baseline uses your current Q01–Q90 answers. It is not your historical saved score. Research or scoring updates, and edits to earlier answers, can change that historical comparison separately. Adding an answer can lower an average even when the answer is fairly close.</p>`:''}${r.conflictPenalty?`<p><b>Key-policy conflict:</b> ${r.conflicts.map(x=>esc(x.id)).join(', ')} · ${r.unpenalizedRaw.toFixed(1)}% before the conflict penalty → ${r.policyRaw.toFixed(1)}% after subtracting ${r.conflictPenalty.toFixed(1)} percentage points.</p>`:''}${axisBreakdown}<ul class="position-list">${r.items.map(x=>`<li><b>${esc(x.id)} · ${esc(x.question.text)}</b><br>You: ${esc(positionAnswer(x.question,x.answer))}<br>Profile: ${x.options.map(a=>esc(positionAnswer(x.question,a))).join(' / ')}<br>Item similarity: ${(x.similarity*100).toFixed(1)}% · ${esc(evidenceLabel(x.position))} · weight ${x.weight}<p>${esc(x.position.rationale)}</p>${sourceLinks(r.profile,x.position.sourceIds)}</li>`).join('')}</ul></details>`;
}
function historicalLimits(r){
 if(r.scope!=='overall'||r.profile.kind!=='Political personality')return '';
 const economic=M.scoreProfile(r.profile,answers,D.questions,'Economics');
 return `<p class="notice small">Historical or contemporary parallel, not your complete identity.${economic.compared<4?` Only ${economic.compared} economic answers compared; this result does not establish a close economic fit.`:''} Shared policies do not establish shared motives, theology, or historical context.</p>`;
}
function fieldResearchNotice(p){if(!p.fieldResearchScope)return '';p={...p,positions:Object.fromEntries(Object.entries(p.positions??{}).filter(([,pos])=>!pos.rationale?.startsWith('Provisional L50 v2: ')))};const r=M.scoreProfile(p,{},D.questions,p.fieldResearchScope),o=M.scoreProfile(p,{},D.questions,'overall');const domains=[[3,4,5,6,7],[0,1,2,10],[8,9]].filter(g=>D.questions.some(q=>g.includes(q.axis)&&M.isSupported(p,p.positions[q.id]))).length;const level=o.availableEligible?5:o.available?Math.min(4,1+Math.floor(4*Math.min(1,o.available/12,o.availableAxes/8,domains/3))):0;const fl=r.availableEligible?5:r.available?Math.min(4,1+Math.floor(4*Math.min(1,r.available/4))):0;return `<p class="notice small">${p.fieldResearchQualificationType==='Historical'?'Historical field-only research':'Field-only research'}: L${fl} in ${esc(p.fieldResearchScope)} · Overall L${level}. ${r.available} documented field positions. This does not establish an overall qualification. Provisional mappings shown separately do not upgrade these research levels.</p>`;}
function matchCard(r,rank){const p=r.profile,isPerson=p.kind.includes('personality');return `<article class="profile-card match-card ${isPerson?'has-portrait':''}"><div class="match-top"><span class="placeholder-rank">${rank?String(rank).padStart(2,'0')+' / ':''}${r.scope==='overall'?'OVERALL':esc(r.scope).toUpperCase()}</span><span class="compatibility">${r.equalization?r.equalization.rankingScore:r.score}<small>%</small><span class="score-label">${r.equalization?'temporary rank':'similarity'}</span></span></div><div class="${isPerson?'match-person':'match-identity'}">${isPerson?portrait(p):''}<div><h3>${esc(resultName(p))}</h3>${p.period?`<p class="person-period">${esc(p.period)}</p>`:''}<p>${esc(p.summary)}</p></div></div>${isPerson?portraitCredit(p):''}${r.equalization?`<p class="notice small">Temporary equalized ranking · documented similarity ${r.score}%. ${r.equalization.normalEligible?'Meets normal qualification.':'Below normal qualification; included temporarily.'} Unknown evidence contributes neutral ranking values, not assumed answers.</p>`:''}${r.conflictPenalty?`<p class="notice small"><b>Important trade-policy disagreement:</b> Your Q100 answer and this profile take opposing sides on protective tariffs for an ordinary new industry. The displayed score includes a ${r.conflictPenalty.toFixed(0)}-point penalty.</p>`:''}${fieldResearchNotice(p)}${matchReasons(r)}${historicalLimits(r)}${r.scope==='Economics'&&(r.compared<8||r.axes<2)?'<p class="notice small">Narrow economic parallel: limited compared evidence. A high similarity here does not establish a close fit across economic policy.</p>':''}${r.scoreLow!==r.scoreHigh?`<p class="small muted">Interpretation range: ${r.scoreLow}–${r.scoreHigh}% across mapped alternatives. This is not a statistical confidence interval.</p>`:''}<p class="coverage">${r.compared} of ${r.available} documented positions compared with your answers${r.scope==='overall'?' · '+r.axes+'/12 dimensions':''} · ${esc(evidenceCounts(r.items))}</p><p class="small muted">Profile research: ${r.available} of ${r.total} relevant questions documented; ${r.total-r.available} not documented.${r.available>r.compared?` ${r.available-r.compared} documented ${r.available-r.compared===1?'position':'positions'} excluded because your answer is unanswered, unsure, or mixed.`:' All documented positions in this comparison were used.'}</p><details><summary>Agreements, differences & sources</summary>${r.agreements.map(x=>witness(p,x,'Agreement')).join('')}${r.differences.length?r.differences.map(x=>witness(p,x,'Difference')).join(''):'<p>No substantial disagreement found in the compared evidence. Uncovered positions remain unknown.</p>'}</details>${calculationDetails(r)}${researchDetails(p)}</article>`;}

function catalogCard(p){const profile=profileFor(p.id),n=Object.keys(profile?.positions??{}).length;return `<article class="profile-card"><h3>${esc(p.name)}</h3><p>${esc(p.fields?.join(' · ')??'')}</p><p style="margin-top:8px">${profile?`${n} documented positions · ${profile.sources.length} sources`:'Evidence review pending'}</p>${profile?fieldResearchNotice(profile)+researchDetails(profile):''}</article>`;}
function profileCards(items){return items.map(catalogCard).join('');}
function poolNotice(profiles,scope='overall'){
 if(temporaryRanking){const n=profiles.filter(p=>R.canRank(p,answers,D.questions,scope)).length;return `<div class="notice"><b>Temporary equalization active: ${n} of ${profiles.length} candidates have at least one documented answer to compare.</b> Everyone uses the same answered question set. Unknown profile positions contribute 50 to the ranking calculation only. No bonus or tie-break favors more researched profiles. Source-backed similarity and normal qualification remain visible.</div>`;}
 const scored=profiles.map(p=>M.scoreProfile(p,answers,D.questions,scope)),excluded=scored.filter(r=>!r.availableEligible),n=profiles.length-excluded.length;
 if(!excluded.length)return '';
 const fieldOnly=scope==='overall'?excluded.filter(r=>Object.keys(M.FIELDS).some(f=>(r.profile.kind!=='Political personality'||D.catalog.find(p=>p.id===r.profile.id)?.fields.includes(f))&&M.scoreProfile(r.profile,answers,D.questions,f)?.availableEligible)).length:0;
 return `<div class="notice"><b>Comparison pool incomplete: ${n} of ${profiles.length} researched candidates meet this comparison’s evidence requirements.</b> Rankings are provisional; a closer candidate may still lack sufficient evidence. This is a research limit, not an unfinished quiz.${scope==='overall'?` Of the excluded candidates, ${fieldOnly} have sufficient evidence for a narrower field and ${excluded.length-fieldOnly} do not yet meet any field minimum.`:''}<details><summary>See which candidates are excluded and where they can be compared</summary><ul class="position-list">${excluded.map(r=>{const fs=Object.keys(M.FIELDS).filter(f=>(r.profile.kind!=='Political personality'||D.catalog.find(p=>p.id===r.profile.id)?.fields.includes(f))&&M.scoreProfile(r.profile,answers,D.questions,f)?.availableEligible);return `<li><b>${esc(r.profile.name)}</b> · ${r.available} documented questions, ${r.availableAxes} dimensions.${fs.length?` Available evidence in: ${fs.map(esc).join(', ')}.`:' No field meets its evidence minimum yet.'}</li>`;}).join('')}</ul></details></div>`;
}
function personalityFieldCandidates(f,candidates=P.filter(p=>p.kind==='Political personality')){const ids=new Set(D.catalog.filter(p=>p.kind==='Political personality'&&p.fields.includes(f)).map(p=>p.id));return candidates.filter(p=>ids.has(p.id));}
function economicRanks(candidates=P.filter(p=>p.kind==='Political personality'),a=answers,qs=D.questions){const ranked=R.rank(personalityFieldCandidates('Economics',candidates),a,qs,'Economics',P.length);if(temporaryRanking)return {broad:ranked,limited:[]};return {broad:ranked.filter(r=>r.compared>=8&&r.axes>=2),limited:ranked.filter(r=>r.compared<8||r.axes<2)};}
function fieldPersonalityRanks(f,a=answers,qs=D.questions,limit=1){const ids=new Set(D.catalog.filter(p=>p.kind==='Political personality'&&p.fields.includes(f)).map(p=>p.id)),all=P.filter(p=>p.kind==='Political personality');if(f==='Economics'){const tiers=economicRanks(all,a,qs);return (tiers.broad.length?tiers.broad:tiers.limited).slice(0,limit);}return R.rank(all.filter(p=>ids.has(p.id)),a,qs,f,limit);}
function byFieldPersonalityMatches(a=answers,qs=D.questions){const pools=new Map(fields.map(f=>[f,fieldPersonalityRanks(f,a,qs,P.length)])),best=new Map();const percent=r=>r.equalization?.rankingScore??r.score,raw=r=>r.equalization?.rankingRaw??r.raw;for(const [field,rows] of pools)for(const row of rows){const prev=best.get(row.profile.id);if(!prev||percent(row)>percent(prev.row)||(percent(row)===percent(prev.row)&&raw(row)>raw(prev.row)))best.set(row.profile.id,{field,row});}return Object.fromEntries([...pools].map(([field,rows])=>[field,rows.find(row=>best.get(row.profile.id)?.field===field)??null]));}
function economicOutlook(){
 const all=personalityFieldCandidates('Economics'),tiers=economicRanks(all),matches=tiers.broad.slice(0,3),ids=new Set(D.catalog.filter(p=>p.kind==='Supplementary profile'&&p.fields.includes('Economics')).map(p=>p.id)),traditions=R.rank(P.filter(p=>ids.has(p.id)),answers,D.questions,'Economics',4);
 const focus=['Q49','Q91','Q94','Q92','Q93','Q95','Q96','Q97','Q98','Q99','Q100','Q101'];
 const pairs=matches.length>1?M.sharedComparison(matches[0].profile,matches[1].profile,answers,D.questions,'Economics'):null;
 return `<p class="subhead">Your economic outlook stands on its own. Religion, moral conservatism, and views on political authority do not decide these matches. A combination of Christian commitments and state-led development need not have one historical namesake.</p><details><summary>Your ownership, investment, welfare, competition, and monetary choices</summary><ul class="position-list">${focus.map(id=>{const q=D.questions.find(q=>q.id===id);return `<li><b>${esc(q.text)}</b><br>${esc(labelFor(id)??'Not answered substantively')}</li>`;}).join('')}</ul></details><p class="small muted">Economic similarity averages supported questions with evidence weights, then subtracts a penalty for a clearly opposed position on Q100. Inferred alternatives use their average fit, not just the most flattering option. These are editorial comparisons, not confidence probabilities.</p><h3>${temporaryRanking?'Temporarily equalized economic matches':'More extensively compared economic matches'}</h3><p class="small muted">${temporaryRanking?'Figures selected for substantial economic work or policy leadership participate when they have supported economic answers.':'At least eight compared questions across two dimensions. Narrower matches appear separately; this display rule does not inflate or penalize their similarity scores.'}</p>${matches.length?`<div class="match-grid">${matches.map((r,i)=>matchCard(r,i+1)).join('')}</div>`:'<p class="notice">No broader economic comparison yet. Answering supplements may help where profiles have supporting evidence. Narrower parallels are listed below.</p>'}${leastSimilar(tiers.broad,matches,1,'Least similar economic parallel')}${tiers.limited.length?`<details><summary>${tiers.limited.length} narrower economic parallels · fewer than eight comparisons or only one dimension</summary><div class="match-grid">${tiers.limited.slice(0,3).map(r=>matchCard(r,null)).join('')}</div><p class="small muted">Only the three closest narrow parallels are expanded here; all profiles remain in the candidate catalog.</p></details>`:''}${pairs?`<p class="notice"><b>Same-question check:</b> ${esc(matches[0].profile.name)} and ${esc(matches[1].profile.name)} share ${pairs.count} answered economic questions. ${pairs.sufficient?`On just those questions: ${pairs.left}% and ${pairs.right}% similarity, respectively. This diagnostic can differ from their full-evidence ranking.`:'Too little shared evidence for a useful head-to-head percentage.'} Their main scores may compare different subsets.</p>`:''}<details><summary>Compare Röpke, Deng, and Lee on documented economics</summary><div class="economic-comparison">${['NP073','P057','P161'].map(id=>all.find(p=>p.id===id)).filter(Boolean).map(p=>{const r=M.scoreProfile(p,answers,D.questions,'Economics');return `<article class="profile-card"><h3>${esc(p.name)}</h3><p>${r.eligible?r.score+'% similarity':'Not enough comparable answers'} · ${r.compared}/${r.available} documented economic positions compared</p>${r.eligible?matchReasons(r):''}${calculationDetails(r)}${calculationDetails(M.scoreProfile(p,answers,D.questions,'overall'))}${researchDetails(p)}</article>`;}).join('')}</div></details><h3>Economic traditions, separately from whole ideologies</h3><p class="small muted">Analytical models of economic institutions only. Their labels do not assign a religion, party, or constitutional system to you.</p>${traditions.length?`<div class="match-grid">${traditions.map((r,i)=>matchCard(r,i+1)).join('')}</div>`:noMatch('Economics')}`;
}
function noMatch(scope){if(temporaryRanking)return '<div class="field-card"><h3>No documented comparison yet</h3><p>Temporary ranking requires at least one supported position that you answered substantively. Unknown answers alone cannot produce a match.</p></div>';return `<div class="field-card"><h3>No sufficiently supported match yet</h3><p>${scope==='overall'?'Overall comparisons need evidence across political institutions, social or religious outlook, and economics.':'This field needs at least '+(scope==='AI outlook'?'three':'four')+' supported positions that you answered substantively.'} Sparse evidence and unsure answers are excluded rather than treated as neutral.</p></div>`;}
function leastSimilar(ranked,closest,count,label){
 const excluded=new Set(closest.map(r=>r.profile.id));
 const matches=ranked.filter(r=>!excluded.has(r.profile.id)).sort((a,b)=>(a.equalization?.rankingRaw??a.raw)-(b.equalization?.rankingRaw??b.raw)||b.compared-a.compared||a.profile.name.localeCompare(b.profile.name)).slice(0,count);
 if(!matches.length)return '';
 return `<section class="least-similar" data-least-similar="${esc(label)}"><h3>${esc(label)}</h3><p class="small muted">Lowest similarity among the remaining sufficiently supported comparisons in this pool. Missing evidence is not treated as disagreement.</p><div class="match-grid">${matches.map(r=>matchCard(r,null)).join('')}</div></section>`;
}
function people(){const all=P.filter(p=>p.kind==='Political personality');if(peopleTab==='overall'){const ranked=R.rank(all,answers,D.questions,'overall',P.length),matches=ranked.slice(0,8);return `${poolNotice(all)}<p class="subhead">${temporaryRanking?'Temporary ranks include profiles below normal qualification.':matches.length+' of eight match slots have sufficient evidence for your answers. Overall profiles need at least eight dimensions and twelve documented questions.'} ${temporaryRanking?'Primary percentages show temporary ranking scores; documented similarity is shown separately.':'Percentages describe similarity over the compared evidence.'}</p>${matches.length?`<div class="match-grid">${matches.map((r,i)=>matchCard(r,i+1)).join('')}</div>`:noMatch('overall')}${leastSimilar(ranked,matches,2,'Least similar overall parallels')}<details style="margin-top:22px"><summary class="muted">Explore the ${D.catalog.filter(p=>p.kind==='Political personality').length} selected personalities and their evidence</summary><div class="catalog-grid" style="margin-top:18px">${profileCards(D.catalog.filter(p=>p.kind==='Political personality'))}</div></details>`;}
const uniqueFields=byFieldPersonalityMatches();return `<p class="small muted">Each figure appears once, in their highest-percentage eligible field. Other fields use their next eligible match.</p><div class="field-grid">${fields.map(f=>{const ids=new Set(D.catalog.filter(p=>p.kind==='Political personality'&&p.fields.includes(f)).map(p=>p.id)),candidates=all.filter(p=>ids.has(p.id)&&(temporaryRanking?R.canRank(p,answers,D.questions,f):M.scoreProfile(p,answers,D.questions,f)?.availableEligible)),econ=f==='Economics'?economicRanks(candidates):null,matches=uniqueFields[f]?[uniqueFields[f]]:[];return `<section class="field-card"><h3>${f}</h3>${econ&&!temporaryRanking?'<p class="small muted">Uses the Economics candidate pool and coverage rules. A figure assigned to a higher-percentage field is replaced here by the next eligible match.</p>':''}${matches.length?matchCard(matches[0],null):candidates.length?'<p class="notice">No distinct match for this field: eligible figures have higher percentages in other fields.</p>':noMatch(f)}<details><summary class="muted small">${candidates.length} candidates with sufficient field evidence</summary><div class="names" style="margin-top:12px">${candidates.map(p=>`<span class="name-chip">${esc(p.name)}</span>`).join('')}</div></details></section>`;}).join('')}</div>`;}

function countries(){const names=new Set(D.countries.filter(c=>c.kind===countryTab).map(c=>c.name)),profiles=P.filter(p=>p.kind==='Country'&&names.has(p.name)),ranked=R.rank(profiles,answers,D.questions,'overall',P.length),matches=ranked.slice(0,3);return `${poolNotice(profiles)}<p class="subhead">Dated political orders. Constitutional commitments and government practice are distinguished in each profile. Short names expand into full designations.</p>${matches.length?`<div class="match-grid">${matches.map((r,i)=>matchCard(r,i+1)).join('')}</div>`:noMatch('overall')}${leastSimilar(ranked,matches,1,countryTab==='Modern'?'Least similar present-day country':'Least similar historical country')}<details style="margin-top:18px"><summary class="muted">Browse all ${countryTab.toLowerCase()} candidates</summary><div class="catalog-grid" style="margin-top:15px">${D.countries.filter(c=>c.kind===countryTab).map(c=>{const p=profiles.find(p=>p.name===c.name);return `<article class="profile-card"><h3>${esc(c.short)}</h3><p>${esc(p?.period??c.period)}</p><p>${esc(c.name)}</p><p>${p?Object.keys(p.positions).length+' documented positions':'Evidence review pending'}</p>${p?researchDetails(p):''}</article>`;}).join('')}</div></details>`;}
function ideologies(){const list=P.filter(p=>p.kind==='Overall ideology'),ranked=R.rank(list,answers,D.questions,'overall',P.length),matches=ranked.slice(0,3);return `${poolNotice(list)}${matches.length?`<div class="match-grid">${matches.map((r,i)=>matchCard(r,i+1)).join('')}</div>`:noMatch('overall')}${leastSimilar(ranked,matches,1,'Least similar ideology')}<p class="subhead" style="margin-top:14px">Ideology matches need six documented dimensions and twelve comparable questions spanning institutions, social outlook, and economics. Narrow doctrines remain supplementary.</p><details><summary class="small muted">Explore all ${D.catalog.filter(p=>p.kind==='Overall ideology').length} ideology candidates and evidence</summary><div class="catalog-grid" style="margin-top:15px">${profileCards(D.catalog.filter(p=>p.kind==='Overall ideology'))}</div></details>`;}
const doctrineFields=['Church–state arrangements','Legal theory','Foreign policy','AI outlook'];
function doctrine(f){const ids=new Set(D.catalog.filter(p=>p.kind==='Supplementary profile'&&p.fields.includes(f)).map(p=>p.id));return R.rank(P.filter(p=>ids.has(p.id)),answers,D.questions,f,1)[0]??null;}
function doctrines(){return `<p class="subhead">Narrower doctrines, each compared only on the questions of its own field.</p><div class="field-grid">${doctrineFields.map(f=>{const candidates=D.catalog.filter(p=>p.kind==='Supplementary profile'&&p.fields.includes(f)),match=doctrine(f);return `<section class="field-card"><h3>${f}</h3>${match?matchCard(match,null):noMatch(f)}<details><summary class="muted small">${candidates.length} doctrines</summary><div class="names" style="margin-top:12px">${candidates.map(p=>`<span class="name-chip">${esc(p.name)}</span>`).join('')}</div></details></section>`;}).join('')}</div>`;}
function aiMatches(){const matches=R.rank(P.filter(p=>p.kind==='AI personality'),answers,D.questions,'AI outlook',3);return `<p class="result-label">${esc(labelFor('Q73')??'No substantive development-policy answer')}</p><p class="subhead">Development pace, risk, jobs, open release, international rules, human authority, political-ad disclosure, and likeness consent. Positions are dated; commercial activity alone is not evidence of unrestricted accelerationism.</p>${matches.length?`<div class="match-grid">${matches.map((r,i)=>matchCard(r,i+1)).join('')}</div>`:noMatch('AI outlook')}<details style="margin-top:18px"><summary class="small muted">View all 20 AI profiles</summary><div class="catalog-grid" style="margin-top:15px">${profileCards(D.catalog.filter(p=>p.kind==='AI personality'))}</div></details>`;}
// Constructed descriptions summarize answers, not a fabricated historical profile.
function combinedOutlook(a=answers,qs=D.questions){
 const value=id=>{const i=qs.findIndex(q=>q.id===id);return i<0?null:Number.isInteger(a[i])?a[i]:null;};
 const yes=id=>value(id)!==null&&value(id)>=3,no=id=>value(id)!==null&&value(id)<=1;
 const faith=yes('Q01')?(no('Q02')?'Broad Christian establishment':yes('Q02')?'Confessional Christian establishment':'Christian establishment'):no('Q01')?'Without Christian state establishment':'Religious establishment undecided';
 const development=yes('Q91')||yes('Q93')||value('Q58')===3;
 const economy=!['Q49','Q58','Q91','Q93'].some(id=>value(id)!==null)?'Economic direction undecided':development?'State-led economic development':no('Q91')&&no('Q93')?'Private-led economic coordination':'Mixed economic preferences';
 const sections=[['Religion and public authority',['Q01','Q02','Q03','Q04','Q07','Q12']],['Ownership, markets and development',['Q49','Q58','Q91','Q93','Q94','Q97']],['Welfare and international investment',['Q57','Q59','Q95','Q96']],['Government and opposition',['Q31','Q37','Q38','Q41']],['Social and family policy',['Q14','Q15','Q16']],['Foreign policy',['Q67','Q70','Q71']]];
 return {title:faith+' · '+economy,sections:sections.map(([name,ids])=>({name,items:ids.filter(id=>value(id)!==null).map(id=>{const q=qs.find(q=>q.id===id);return {id,text:q.text,answer:positionAnswer(q,value(id))};})})),qualifications:[
 ...(yes('Q01')&&no('Q02')?['Support for a broad Christian establishment does not by itself establish theological ecumenism or equal rights for other religions.']:[]),
 ...(yes('Q01')&&(no('Q07')||yes('Q12'))?['Your support for Christian establishment accompanies restrictions on other religious expression; this is not unrestricted religious pluralism.']:[]),
 ...(yes('Q91')&&value('Q94')===0?['You combine lasting public ownership with commercially independent enterprise management, rather than treating state ownership and day-to-day state direction as identical.']:[])
 ]};
}
function combinedOutlookMarkup(){const o=combinedOutlook();return `<section class="results-section combined-outlook" aria-labelledby="result-combined"><span class="eyebrow">YOUR COMBINED OUTLOOK</span><h2 id="result-combined">${esc(o.title)}</h2><p>A constructed description from your answers. You can combine traditions without matching any one person or established ideology. This is an editorial summary, not a historical movement, religious identity, or scored candidate.</p>${o.qualifications.map(t=>`<p class="notice small">${esc(t)}</p>`).join('')}<div class="field-grid">${o.sections.map(section=>`<details class="field-card"><summary>${esc(section.name)} · ${section.items.length} answers</summary>${section.items.length?section.items.map(x=>`<p><b>${esc(x.id)} · ${esc(x.text)}</b><br>${esc(x.answer)}</p>`).join(''):'<p>No substantive answers in this selection.</p>'}</details>`).join('')}</div><p class="small muted">The questionnaire has a Christian political-thought emphasis. It does not yet measure every faith, modern synthesis, or regional political tradition equally. The comparisons below are examples from a limited researched pool, not an exhaustive classification.</p></section>`;}
const resultSections=[['overview','Overview'],['ideas','Ideas'],['people','People'],['economics','Economics'],['dimensions','13 dimensions'],['ai','AI outlook'],['countries','Countries'],['doctrines','Doctrines']];
function tabbedResults(markup){
 const start=markup.indexOf('<nav class="result-jump"'),end=markup.indexOf('</nav>',start)+6;
 const body=markup.slice(end),sections=[];let depth=0,offset=0;for(const token of body.matchAll(/<\/?section\b[^>]*>/g)){if(token[0].startsWith('</')){depth--;if(depth===0)sections.push(body.slice(offset,token.index+token[0].length));}else{if(depth===0)offset=token.index;depth++;}}
 const tabs=`<nav class="tabs result-tabs" role="tablist" aria-label="Results sections">${resultSections.map(([id,label])=>`<button class="tab" role="tab" id="result-tab-${id}" aria-controls="result-panel-${id}" aria-selected="${resultTab===id}" tabindex="${resultTab===id?0:-1}" data-result-tab="${id}">${label}</button>`).join('')}</nav>`;
 return markup.slice(0,start)+tabs+sections.map((section,i)=>{const id=resultSections[i][0];return `<div id="result-panel-${id}" role="tabpanel" aria-labelledby="result-tab-${id}"${resultTab===id?'':' hidden'}>${section}</div>`;}).join('');
}
function results(){const n=answers.filter(Number.isInteger).length;const markup=`${temporaryRanking?'<div class="notice"><b>Temporary equalization is ON.</b> Ranks use a common question set with neutral values for unknown profile evidence. These scores are not accuracy probabilities.</div>':''}<div class="result-top"><div><span class="eyebrow">${shared?'SHARED RESULT':'YOUR POLITICAL PORTRAIT'}</span><h1>Principles in perspective.</h1><p class="muted">${answered()}/${D.questions.length} questions answered · ${n} substantive answers · ${answers.filter(x=>x==='u').length} unsure · ${answers.filter(x=>x==='m').length} mixed</p></div><div><div class="result-actions"><button class="primary" data-action="replay">Replay your reveal ✳</button><button class="secondary" data-action="share">Copy result link ↗</button><button class="secondary" data-action="download">Download card ↓</button><button class="secondary" data-action="matches-graphic">Download matches graphic ↓</button><button class="secondary" data-action="review">Edit answers & resubmit</button>${!shared?'<button class="secondary" data-action="history">Saved versions</button>':''}</div><p class="share-note muted small">The quiz is public. A shared result link includes your answers; anyone with that link can view them.</p></div></div>${answers.some(a=>a===null)?`<div class="notice">${D.questions.length-answered()} new, revised or unanswered questions are excluded from this calculation. <button class="secondary" data-action="supplement">Answer supplement</button></div>`:''}<p class="small muted">Question version ${questionVersion} · Calculated from your current answers and current evidence.${shared?' Shared answers do not overwrite your saved history.':storageAvailable?' Submissions are saved in this browser.':' Storage unavailable: download a backup.'}</p><div class="notice">Your quiz completion and profile research coverage are different. Missing profile evidence does not mean you skipped a question, and it is never scored as disagreement. Match percentages describe similarity on the evidence available, not certainty about a full political outlook. These are interpretive comparisons, not scientific diagnoses. Sparse profiles may qualify for a field without qualifying overall.</div><nav class="result-jump" aria-label="Explore results"><button data-scroll="result-economics">Economics</button><button data-scroll="result-people">People</button><button data-scroll="result-ideas">Ideas</button><button data-scroll="dimensions">13 dimensions</button><button data-scroll="result-ai">AI outlook</button></nav>${combinedOutlookMarkup()}<section class="results-section"><span class="eyebrow">IDEOLOGICAL PROXIMITY</span><h2 id="result-ideas">Established ideology comparisons</h2>${ideologies()}</section><section class="results-section"><span class="eyebrow">PEOPLE & PRINCIPLES</span><h2 id="result-people">Find your affinities</h2><div class="tabs" role="tablist" aria-label="Personality comparisons"><button class="tab" role="tab" id="people-overall" aria-controls="people-panel" aria-selected="${peopleTab==='overall'}" data-people="overall">Overall parallels</button><button class="tab" role="tab" id="people-fields" aria-controls="people-panel" aria-selected="${peopleTab==='field'}" data-people="field">By field</button></div><div id="people-panel" role="tabpanel" aria-labelledby="${peopleTab==='overall'?'people-overall':'people-fields'}">${people()}</div></section><section class="results-section"><span class="eyebrow">BEYOND A SINGLE ECONOMIC LABEL</span><h2 id="result-economics">Your economic outlook</h2>${economicOutlook()}</section><section aria-labelledby="dimensions"><div class="section-header"><div><span class="eyebrow">13 DIMENSIONS</span><h2 id="dimensions">The shape of your outlook</h2></div><span class="muted small">Categorical differences preserved</span></div><div class="axis-grid">${axisCards()}</div></section><section class="results-section"><span class="eyebrow">THE NEXT FRONTIER</span><h2 id="result-ai">Your AI outlook</h2>${aiMatches()}</section><section class="results-section"><span class="eyebrow">POLITICAL ORDERS</span><h2>Across places and periods</h2><div class="tabs" role="tablist" aria-label="Country comparisons">${['Modern','Historical'].map(t=>`<button class="tab" role="tab" id="country-${t}" aria-controls="country-panel" aria-selected="${countryTab===t}" data-country="${t}">${t}</button>`).join('')}</div><div id="country-panel" role="tabpanel" aria-labelledby="country-${countryTab}">${countries()}</div></section><section class="results-section"><span class="eyebrow">SPECIFIC DOCTRINES</span><h2>Church, law, war, and AI</h2>${doctrines()}<button class="text-button back-top" data-action="home">← Back to home</button></section>`;return tabbedResults(markup);}
function savedControls(){return `${!storageAvailable?'<p class="notice" role="status">Browser history storage is unavailable. Download a backup before leaving this page.</p>':''}<div class="history-controls"><button class="secondary" data-action="history">Saved versions (${state.submissions.length})</button><button class="text-button" data-action="backup">Download backup</button><button class="text-button" data-action="import">Restore backup</button></div>${state.submissions.length&&answers.some(a=>a===null)?`<p>${D.questions.length-answered()} new, revised or unanswered questions. <button class="text-button" data-action="supplement">Take supplement</button><button class="text-button" data-action="results">Recalculate existing answers</button></p>`:''}`;}
function review(){return `<div class="quiz-container"><span class="eyebrow">REVISIT YOUR POSITIONS</span><h1 style="font-size:36px">Every answer, in view.</h1><p class="muted">Review answers in order, or pick a question to start from. Clicking an answer advances to the next question. Submit at any time to recalculate; previous submissions stay saved.</p><div class="history-controls"><button class="primary review-submit" data-action="results" ${answered()===0?'disabled':''}>Submit updated results</button><button class="secondary" data-action="review-sequence">Review answers in order →</button>${answers.some(a=>a===null)?'<button class="secondary" data-action="supplement">Finish unanswered questions →</button>':''}</div><div class="review-grid">${D.questions.map((q,i)=>`<button data-jump="${i}" class="${answers[i]!==null?'answered':''}" aria-label="Edit question ${i+1}">${i+1}</button>`).join('')}</div><button class="primary" data-action="results" ${answered()===0?'disabled':''}>Submit & recalculate →</button><button class="text-button" data-action="home">Save draft & exit</button></div>`;}
function resultSummary(a=answers,qs=D.questions){
 const compact=rows=>rows.map(r=>({name:resultName(r.profile),score:r.score,...(r.equalization?{rankingScore:r.equalization.rankingScore,rankingMode:R.VERSION}:{}),compared:r.compared,total:r.total,axes:r.axes,scope:r.scope}));
 const groups=[{name:'Overall ideologies',rows:compact(R.rank(P.filter(p=>p.kind==='Overall ideology'),a,qs,'overall',3))},{name:'Overall personalities',rows:compact(R.rank(P.filter(p=>p.kind==='Political personality'),a,qs,'overall',8))},{name:'AI outlook',rows:compact(R.rank(P.filter(p=>p.kind==='AI personality'),a,qs,'AI outlook',3))}];
 for(const type of ['Modern','Historical']){const names=new Set(D.countries.filter(c=>c.kind===type).map(c=>c.name));groups.push({name:type+' countries',rows:compact(R.rank(P.filter(p=>p.kind==='Country'&&names.has(p.name)),a,qs,'overall',3))});}
 const fieldMatches=byFieldPersonalityMatches(a,qs);for(const f of fields){groups.push({name:f+' personality',rows:compact(fieldMatches[f]?[fieldMatches[f]]:[])});}
 for(const f of [...new Set(D.catalog.filter(p=>p.kind==='Supplementary profile').flatMap(p=>p.fields))]){const ids=new Set(D.catalog.filter(p=>p.kind==='Supplementary profile'&&p.fields.includes(f)).map(p=>p.id));groups.push({name:f+' doctrine',rows:compact(R.rank(P.filter(p=>ids.has(p.id)),a,qs,f,1))});}
 const axes=D.axes.map((axis,i)=>{const indices=qs.map((q,j)=>q.axis===i?j:-1).filter(j=>j>=0),vs=indices.filter(j=>Number.isInteger(a[j])).map(j=>qs[j].type==='scale'?[-1,-.5,0,.5,1][a[j]]*qs[j].sign:qs[j].values?.[a[j]]).filter(v=>Number.isFinite(v));return {name:axis.name,answered:indices.filter(j=>Number.isInteger(a[j])).length,total:indices.length,value:vs.length?vs.reduce((x,y)=>x+y,0)/vs.length:null};});
 return {groups,axes,combinedOutlook:combinedOutlook(a,qs),answered:a.filter(v=>v!==null).length,total:qs.length};
}
function submit(){if(!answered())return;editing=false;queue=null;if(!shared){S.submit(state,D.questions,answers,resultSummary(),evidenceVersion);persist();}view='results';revealStart();window.scrollTo({top:0,behavior:'instant'});}
function historyView(){const snap=state.submissions.find(x=>x.id===activeSnapshot);if(snap)return `<section class="quiz-container"><span class="eyebrow">SAVED RESULT · ${esc(snap.kind)}</span><h1>${snap.label?esc(snap.label)+" · ":""}Version from ${esc(new Date(snap.createdAt).toLocaleString())}</h1><p>Question version ${esc(snap.questionVersion)} · Evidence ${esc(snap.evidenceVersion)} · ${esc(snap.result.answered)}/${esc(snap.result.total)} answered. These scores are frozen; they are not recalculated by later updates.</p><button class="primary" data-restore="${esc(snap.id)}">${S.align(snap.entries,D.questions).some(a=>a===null)?'Use saved answers & finish remaining questions':'Review saved answers in order'}</button><button class="secondary" data-restore="${esc(snap.id)}" data-recalculate="true">Recalculate saved answers</button><button class="text-button" data-action="history">All saved versions</button>${snap.result.groups.map(g=>`<section class="history-group"><h2>${esc(g.name)}</h2>${g.rows.length?g.rows.map(r=>`<p><b>${esc(r.name)}</b> · ${esc(r.score)}% · ${esc(r.compared)}/${esc(r.total)} relevant questions used in this saved comparison</p>`).join(''):'<p class="muted">No sufficiently supported match.</p>'}</section>`).join('')}<details><summary>Saved questions and answers</summary>${snap.questions.map(q=>{const a=snap.entries[q.id]?.value;return `<p><b>${esc(q.id)}</b> ${esc(q.text)}<br>${esc(a==null?'Unanswered':a==='u'?'Unsure':a==='m'?'Other / mixed view':q.type==='scale'?scale[a]:q.options[a])}</p>`;}).join('')}</details></section>`;
 return `<section class="quiz-container"><h1>Saved versions</h1><p>Submitted results keep their original questions, answers and calculated matches. Restore one to edit it or answer a supplement. Your previous submissions remain unchanged.</p>${savedControls()}${state.submissions.length?[...state.submissions].reverse().map(x=>`<article class="history-entry"><b>${esc(new Date(x.createdAt).toLocaleString())}</b><p>${esc(x.kind)} · ${esc(x.result.answered)}/${esc(x.result.total)} answered · questions ${esc(x.questionVersion)}</p><button class="secondary" data-snapshot="${esc(x.id)}">View saved result</button></article>`).join(''):'<p>No submitted results yet.</p>'}<button class="text-button" data-action="home">Back to home</button></section>`;}
function revealMarkup(){const item=revealItems[revealIndex];if(!item)return '';if(item.constructed){const o=combinedOutlook();return `<section class="reveal-stage" role="dialog" aria-modal="true" aria-labelledby="reveal-title"><div class="reveal-top"><span class="eyebrow">YOUR COMBINED OUTLOOK</span><button class="text-button" data-action="reveal-close">Skip to full results ↗</button></div><article class="reveal-card reveal-idea"><div class="reveal-emblem" aria-hidden="true"><span>YOUR OWN COMBINATION</span><i>✳</i></div><div class="reveal-copy"><h1 id="reveal-title">${esc(o.title)}</h1><p>A description built from your answers, before comparing you with historical figures or established schools.</p><p>${esc(o.qualifications[0]??'Your economic, social, religious and governing preferences can cross conventional labels.')}</p><p class="small muted">Constructed summary · No invented match percentage · Explore the supporting answers in your full results.</p></div></article><div class="reveal-controls"><button class="text-button" data-action="reveal-pause">${revealPaused?'Play':'Pause'}</button><button class="primary" data-action="reveal-next">Explore comparisons →</button></div><p class="reveal-note">${revealPaused?'Paused · Explore at your own pace.':'Advances every 9 seconds · Pause to take your time.'}</p></section>`;}const r=item.result,p=r.profile,isPerson=p.kind.includes('personality');return `<section class="reveal-stage" role="dialog" aria-modal="true" aria-labelledby="reveal-title"><div class="reveal-top"><span class="eyebrow">YOUR PORTRAIT, REVEALED</span><button class="text-button" data-action="reveal-close">Skip to full results ↗</button></div><div class="reveal-progress" aria-hidden="true"><i style="width:${(revealIndex+1)/revealItems.length*100}%"></i></div><article class="reveal-card ${isPerson?'':'reveal-idea'}" aria-live="polite">${isPerson?portrait(p,true):`<div class="reveal-emblem" aria-hidden="true"><span>${String(revealIndex+1).padStart(2,'0')}</span><i>✳</i></div>`}<div class="reveal-copy"><span class="result-kicker">${esc(item.label)}</span><h1 id="reveal-title">${esc(resultName(p))}</h1><div class="reveal-score"><strong>${r.equalization?r.equalization.rankingScore:r.score}<small>%</small></strong><span>${r.equalization?'temporary equalized ranking':'similarity on documented answers'}</span></div>${r.equalization?`<p class="small muted">Documented similarity ${r.score}% · ${r.equalization.normalEligible?'Normally qualified':'Below normal qualification'}</p>`:''}<p class="reveal-bio">${esc(p.summary)}</p>${matchReasons(r,1)}${isPerson?portraitCredit(p):''}</div></article><div class="reveal-controls"><button class="secondary" data-action="reveal-back" ${revealIndex===0?'disabled':''}>← Previous</button><div class="reveal-dots" aria-label="Reveal progress">${revealItems.map((x,i)=>`<button data-reveal-index="${i}" aria-label="Show ${esc(x.label)}" aria-current="${i===revealIndex?'step':'false'}">${i+1}</button>`).join('')}</div><button class="text-button" data-action="reveal-pause">${revealPaused?'Play':'Pause'}</button><button class="primary" data-action="reveal-next">${revealIndex===revealItems.length-1?'Explore all results':'Next match'} →</button></div><p class="reveal-note">${revealPaused?'Paused · Explore at your own pace.':'Advances every 9 seconds · Pause to take your time.'} Use arrow keys to navigate, Escape to close. Comparisons are interpretive, not scientific diagnoses.</p></section>`;}
function revealStart(){
 clearTimeout(revealTimer);revealItems=answers.some(Number.isInteger)?[{label:'Your combined outlook',constructed:true}]:[];
 const ideology=R.rank(P.filter(p=>p.kind==='Overall ideology'),answers,D.questions,'overall',1)[0];if(ideology)revealItems.push({label:'Your closest school of thought',result:ideology});
 R.rank(P.filter(p=>p.kind==='Political personality'),answers,D.questions,'overall',3).forEach((r,i)=>revealItems.push({label:`Political affinity / ${String(i+1).padStart(2,'0')}`,result:r}));
 const ai=R.rank(P.filter(p=>p.kind==='AI personality'),answers,D.questions,'AI outlook',1)[0];if(ai)revealItems.push({label:'A separate perspective / AI',result:ai});
 revealIndex=revealItems.length?0:null;revealPaused=reducedMotion();render();
}
function revealClose(){clearTimeout(revealTimer);revealIndex=null;render();document.querySelector('[data-action="replay"]')?.focus?.({preventScroll:true});}
function revealMove(step){clearTimeout(revealTimer);const next=revealIndex+step;if(next>=revealItems.length){revealClose();return;}revealIndex=Math.max(0,next);render();}
function render(){
 clearTimeout(revealTimer);document.body?.setAttribute('data-view',view);
 const active=view==='results'&&revealIndex!==null;
 app.innerHTML=view==='home'?home():view==='quiz'?quiz():view==='review'?review():view==='history'?historyView():`<div class="results-content" ${active?'inert':''}>${results()}</div>${active?revealMarkup():''}`;
 if(active){document.querySelector('[data-action="reveal-next"]')?.focus?.({preventScroll:true});if(!revealPaused)revealTimer=setTimeout(()=>revealMove(1),9000);}
}

function archiveDraft(){const a=shared?S.align(state.draft.entries,D.questions):answers;if(a.some(v=>v!==null))S.submit(state,D.questions,a,resultSummary(a),evidenceVersion,'saved draft');}
function start(){if(answered()&&!confirm('Start a new test? Your current answers will be kept in saved versions.'))return;archiveDraft();answers=Array(D.questions.length).fill(null);index=0;shared=false;editing=false;queue=null;history.replaceState(null,'',location.pathname+location.search);persist();change('quiz');}
function beginReview(start=0){editing=true;queue=null;index=start;persist();change('quiz');}
function supplement(){queue=D.questions.map((q,i)=>answers[i]===null?i:-1).filter(i=>i>=0);editing=false;if(!queue.length){submit();return;}index=queue[0];persist();change('quiz');}
function downloadFile(text,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){if(!shared)S.update(state,D.questions,answers,index);downloadFile(JSON.stringify(state,null,2),'civic-spectrum-history.json','application/json');}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{const file=input.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error();const incoming=S.load(await file.text(),null,D.questions,LEGACY);if(!incoming.submissions.every(x=>Array.isArray(x.questions)&&x.entries&&Array.isArray(x.result?.groups)&&x.result.groups.every(g=>typeof g.name==='string'&&Array.isArray(g.rows))))throw Error();archiveDraft();const ids=new Map(state.submissions.map(x=>[x.id,x]));for(const x of incoming.submissions){if(ids.has(x.id)&&JSON.stringify(ids.get(x.id))===JSON.stringify(x))continue;while(ids.has(x.id))x.id+='-imported';state.submissions.push(x);ids.set(x.id,x);}state.draft=incoming.draft;answers=S.align(state.draft.entries,D.questions);index=0;shared=false;history.replaceState(null,'',location.pathname+location.search);persist();activeSnapshot=null;change('history');toast(storageAvailable?'Backup restored. Existing submitted versions were preserved.':'Backup loaded in memory only. Download it before leaving; storage is unavailable.');}catch{toast('This backup could not be restored. Your existing history is unchanged.');}});input.click();}
async function share(){if(!answered()){toast('Answer a question before sharing.');return;}const encoded=btoa(JSON.stringify({version:3,entries:S.entries(D.questions,answers)})).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const url=location.origin+location.pathname+'#r='+encoded;try{await navigator.clipboard.writeText(url);toast('Result link copied. It includes your answers.');}catch{prompt('Copy this result link. It includes your answers:',url);}}

async function downloadMatchesGraphic(){
 const fieldMatches=byFieldPersonalityMatches();
 const groups=[{name:'Overall parallels',rows:R.rank(P.filter(p=>p.kind==='Political personality'),answers,D.questions,'overall',8)},
 {name:'By field',rows:fields.map(f=>{const r=fieldMatches[f];return r?{...r,field:f}:null;}).filter(Boolean)},
 ...['Modern','Historical'].map(type=>{const names=new Set(D.countries.filter(c=>c.kind===type).map(c=>c.name));return {name:type+' countries',rows:R.rank(P.filter(p=>p.kind==='Country'&&names.has(p.name)),answers,D.questions,'overall',3)};}),
 {name:'Ideology comparisons',rows:R.rank(P.filter(p=>p.kind==='Overall ideology'),answers,D.questions,'overall',3)}];
 try{await window.CivicMatchesGraphic.download(groups,{name:resultName,temporary:temporaryRanking,portraits:window.CIVIC_PORTRAITS??{}});toast('Matches graphic downloaded.');}catch{toast('Could not create the matches graphic. Please try again.');}
}

function wrap(ctx,text,x,y,width,line){const words=text.split(' ');let row='';for(const w of words){if(ctx.measureText(row+w).width>width&&row){ctx.fillText(row,x,y);y+=line;row='';}row+=w+' ';}ctx.fillText(row,x,y);return y+line;}
function download(){const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1640;const c=canvas.getContext('2d');c.fillStyle='#f5f5ee';c.fillRect(0,0,1200,1640);c.fillStyle='#276c62';c.font='bold 20px sans-serif';c.fillText('CIVIC SPECTRUM / RESEARCH EDITION',70,75);c.fillStyle='#183b35';c.font='bold 52px sans-serif';c.fillText('My political portrait',70,160);c.fillStyle='#586c65';c.font='20px sans-serif';c.fillText(D.questions.length+' questions · 13 dimensions · Provisional answer summaries',70,207);stats().forEach((a,i)=>{const y=270+i*90;c.fillStyle='#183b35';c.font='bold 21px sans-serif';c.fillText(a.name,70,y);c.font='16px sans-serif';c.fillStyle='#586c65';if(categoryQuestions[i]){const state=categoryState(i);c.fillText('Position options · '+state.q.id,70,y+29);c.textAlign='right';c.fillText(state.selected?'Option '+(state.answer+1)+' of '+state.q.options.length:'No option selected',1130,y+29);c.textAlign='left';const gap=6,width=(1060-gap*(state.q.options.length-1))/state.q.options.length;state.q.options.forEach((_,j)=>{c.fillStyle=state.selected&&j===state.answer?a.color:'#dfe7df';c.fillRect(70+j*(width+gap),y+43,width,10);});c.fillStyle='#586c65';c.font='14px sans-serif';const label=state.label;let shown=label;while(c.measureText(shown).width>1060&&shown.length>3)shown=shown.slice(0,-2);c.fillText(shown===label?shown:shown+'…',70,y+74);}else{c.fillText(a.left,70,y+29);c.textAlign='right';c.fillText(a.right,1130,y+29);c.textAlign='left';c.fillStyle='#dfe7df';c.fillRect(70,y+43,1060,10);if(a.v!==null){const split=(a.v+1)/2*1060;c.fillStyle=a.color;c.fillRect(70,y+43,split,10);c.fillStyle=a.rightColor;c.fillRect(70+split,y+43,1060-split,10);}}});c.fillStyle='#276c62';c.font='18px sans-serif';wrap(c,'Provisional answer summary. Source-backed matches and evidence coverage are available in the full interactive result.',70,1480,1060,27);c.fillStyle='#586c65';c.font='16px sans-serif';c.fillText('Civic Spectrum · '+location.hostname,70,1585);canvas.toBlob(blob=>{if(!blob){toast('Could not generate the image.');return;}const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='civic-spectrum-result.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Result card downloaded.');},'image/png');}
function advance(){if(answers[index]===null)return;persist();if(queue){const next=queue.find(i=>i>index&&answers[i]===null)??queue.find(i=>answers[i]===null);if(next!==undefined){index=next;persist();change('quiz');}else submit();return;}if(index<D.questions.length-1){index++;persist();change('quiz');}else if(answered()===D.questions.length)submit();else supplement();}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.resultTab){resultTab=b.dataset.resultTab;const y=window.scrollY;render();window.scrollTo(0,y);app.querySelector(`[data-result-tab="${resultTab}"]`)?.focus({preventScroll:true});return;}if(b.dataset.scroll){document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:reducedMotion()?'instant':'smooth',block:'start'});return;}if(b.dataset.revealIndex!==undefined){revealIndex=Number(b.dataset.revealIndex);render();return;}if(b.dataset.action==='replay'){revealStart();return;}if(b.dataset.action==='reveal-close'){revealClose();return;}if(b.dataset.action==='reveal-next'){revealMove(1);return;}if(b.dataset.action==='reveal-back'){revealMove(-1);return;}if(b.dataset.action==='reveal-pause'){revealPaused=!revealPaused;render();return;}if(b.dataset.answer!==undefined){const v=b.dataset.answer,value=v==='u'||v==='m'?v:Number(v);if(!S.validAnswer(D.questions[index],value))return;answers[index]=value;advance();return;}if(b.dataset.people){peopleTab=b.dataset.people;const y=window.scrollY;render();window.scrollTo(0,y);app.querySelector(`[data-people="${peopleTab}"]`)?.focus({preventScroll:true});return;}if(b.dataset.country){countryTab=b.dataset.country;const y=window.scrollY;render();window.scrollTo(0,y);app.querySelector(`[data-country="${countryTab}"]`)?.focus({preventScroll:true});return;}if(b.dataset.snapshot){activeSnapshot=b.dataset.snapshot;change('history');return;}if(b.dataset.restore){const snap=state.submissions.find(x=>x.id===b.dataset.restore);if(!snap)return;archiveDraft();answers=S.restore(state,snap,D.questions);shared=false;index=0;history.replaceState(null,'',location.pathname+location.search);persist();if(b.dataset.recalculate==='true')submit();else if(answers.some(a=>a===null))supplement();else beginReview();return;}if(b.dataset.jump!==undefined){beginReview(Number(b.dataset.jump));return;}const a=b.dataset.action;if(a==='start')start();if(a==='resume'){if(editing)beginReview(index);else if(answered()===D.questions.length)submit();else supplement();}if(a==='back'){const previous=queue?queue[queue.indexOf(index)-1]:index-1;if(previous!==undefined&&previous>=0){index=previous;persist();change('quiz');}}if(a==='next')advance();if(a==='home'||a==='save-exit'){persist();change('home');}if(a==='review'){editing=true;queue=null;change('review');}if(a==='review-sequence')beginReview();if(a==='results')submit();if(a==='supplement')supplement();if(a==='history'){activeSnapshot=null;change('history');}if(a==='backup')backup();if(a==='import')importBackup();if(a==='share')share();if(a==='download')download();if(a==='matches-graphic')downloadMatchesGraphic();});

app.addEventListener('error',e=>{if(e.target?.tagName==='IMG'){e.target.hidden=true;e.target.parentElement?.classList.add('image-unavailable');}},true);
window.addEventListener('keydown',e=>{
 if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('#info')?.open)return;
 if(revealIndex!==null&&view==='results'){
  if(e.key==='Escape'){e.preventDefault();revealClose();}else if(e.key==='ArrowRight'){e.preventDefault();revealMove(1);}else if(e.key==='ArrowLeft'){e.preventDefault();revealMove(-1);}else if(e.key==='Tab'){const nodes=[...app.querySelectorAll('.reveal-stage button:not(:disabled), .reveal-stage a, .reveal-stage summary')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;
 }
 if(view==='results'&&document.activeElement?.dataset?.resultTab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const ids=resultSections.map(x=>x[0]),i=ids.indexOf(resultTab);resultTab=ids[e.key==='Home'?0:e.key==='End'?ids.length-1:(i+(e.key==='ArrowRight'?1:-1)+ids.length)%ids.length];render();app.querySelector(`[data-result-tab="${resultTab}"]`)?.focus({preventScroll:true});return;}
 if(view==='quiz'&&/^[1-9]$/.test(e.key)){const n=Number(e.key)-1,q=D.questions[index];if(n<(q.type==='scale'?5:q.options.length)){e.preventDefault();answers[index]=n;advance();}}
});
document.querySelector('#brand').addEventListener('click',()=>{persist();change('home');});for(const id of ['about','method'])document.querySelector('#'+id).addEventListener('click',()=>document.querySelector('#info').showModal());document.querySelector('#close-info').addEventListener('click',()=>document.querySelector('#info').close());
window.addEventListener('hashchange',()=>{if(decodeHash())render();});if(legacyImported&&answers.some(a=>a!==null)){S.submit(state,D.questions,answers,resultSummary(),evidenceVersion,'imported answers (recalculated)');persist();}decodeHash();render();
})();

